<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {api} from './api';
import Dialog from './Dialog.vue';
const props=defineProps<{run:(work:()=>Promise<void>)=>Promise<void>;busy:boolean;requestError?:string}>();
const data=ref<{configured:boolean;prefix:string;allowedIps:string[];createdAt:string|null}|null>(null),secret=ref(''),error=ref(''),notice=ref(''),regenerate=ref(false),whitelist=ref(false),ips=ref<string[]>([]);
const address=location.origin+'/v1/integration';
async function load(){data.value=await api('operator/api');}
async function generate(){await props.run(async()=>{const result=await api<{secret:string}>('operator/api',{action:'REGENERATE'});secret.value=result.secret;regenerate.value=false;notice.value='Copy this key now. It is shown only once.';await load();});}
function openIps(){ips.value=[...(data.value?.allowedIps||[])];whitelist.value=true;}
async function saveIps(){await props.run(async()=>{await api('operator/api',{action:'WHITELIST',ips:ips.value.map(s=>s.trim()).filter(Boolean)});whitelist.value=false;await load();notice.value='IP whitelist saved.';});}
async function copy(value:string){await props.run(async()=>{await navigator.clipboard.writeText(value);notice.value='Copied.';});}
async function download(){await props.run(async()=>{const result=await api<{text:string}>('operator/api/documentation');const url=URL.createObjectURL(new Blob([result.text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='New-Game-Operator-API.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
onMounted(()=>{void load().catch(e=>error.value=(e as Error).message);});
</script>
<template><section class="api-page"><h1>Download</h1><p class="muted centered">Download API documentation and configuration information</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div class="api-cards"><section class="panel"><h2 class="panel-heading">API Secret Key</h2><div class="panel-body"><output class="secret-value">{{secret||(data?.configured?data.prefix+'••••••••••••••••••':'Not generated')}}</output><div class="actions"><button class="primary" :disabled="busy||!secret" @click="copy(secret)">Copy</button><button class="danger" :disabled="busy" @click="regenerate=true">Regenerate</button></div><p class="fine">A new key is shown once. Regenerating invalidates the previous key.</p></div></section><section class="panel"><h2 class="panel-heading">API Whitelist IP</h2><div class="panel-body"><p>Only IP addresses in the whitelist can access the API. An empty list denies all requests.</p><button class="primary" :disabled="busy||!data?.configured" @click="openIps">API Whitelist IP</button></div></section></div><section class="panel"><h2 class="panel-heading">API Documentation</h2><div class="panel-body"><h3>API Documentation Download</h3><p>Download endpoint details, authentication and response formats.</p><button class="primary" :disabled="busy" @click="download">Download Documentation</button><h3>Official API Address</h3><div class="filter-row"><input :value="address" aria-label="Official API Address" readonly><button :disabled="busy" @click="copy(address)">Copy</button></div><p class="fine">The integration API provides branch-scoped account and activity reads. Account and credit changes use the operator console.</p></div></section><section class="panel"><h2 class="panel-heading">API Common Questions</h2><div class="panel-body"><h3>How to configure Secret Key and API IP Whitelist?</h3><p>Generate a key, copy it into your server's secret storage, then allow that server's outgoing IP address.</p><h3>What is the Agent ID in the API?</h3><p>Find your Agent ID on the Setting page.</p></div></section></section><Dialog v-if="regenerate" title="Regenerate API Secret Key" :busy="busy" @close="regenerate=false"><p>The previous key will stop working. The new key will be shown once.</p><p v-if="requestError" class="error" role="alert">{{requestError}}</p><footer><button :disabled="busy" @click="regenerate=false">Cancel</button><button class="primary" :disabled="busy" @click="generate">Confirm</button></footer></Dialog><Dialog v-if="whitelist" title="API Whitelist IP" :busy="busy" @close="whitelist=false"><div v-for="(_,i) in ips" :key="i" class="filter-row"><input v-model="ips[i]" :aria-label="`IP address ${i+1}`" placeholder="IPv4 or IPv6 address"><button :disabled="busy" @click="ips.splice(i,1)">Remove</button></div><button :disabled="busy||ips.length>=20" @click="ips.push('')">＋ Add IP</button><p v-if="requestError" class="error" role="alert">{{requestError}}</p><footer><button :disabled="busy" @click="whitelist=false">Cancel</button><button class="primary" :disabled="busy" @click="saveIps">Confirm</button></footer></Dialog></template>
